export const HUAANWORK_STYLES = "/* HuaAnWork — 纸面工作台 Paper Workbench（见 DESIGN.md） */\n\n:root {\n  --bg: #FAFAF8;\n  --surface: #FFFFFF;\n  --sidebar-bg: #F4F3EF;\n  --text: #1B1B1F;\n  --text-muted: #6E6E73;\n  --text-faint: #9B9BA0;\n  --border: #E6E4DE;\n  --border-strong: #D8D5CC;\n  --accent: #3A4ED0;\n  --accent-soft: #EEF0FC;\n  --accent-ink: #2C3DA8;\n  --approval: #B7791F;\n  --approval-bg: #FDF8EC;\n  --approval-border: #EADFC2;\n  --success: #2F7D4F;\n  --error: #B3382C;\n  --error-bg: #FBEEEC;\n  --shadow-card: 0 1px 2px rgba(27, 27, 31, 0.04), 0 4px 16px rgba(27, 27, 31, 0.05);\n  --shadow-hover: 0 1px 3px rgba(27, 27, 31, 0.06), 0 6px 24px rgba(27, 27, 31, 0.08);\n  --shadow-pop: 0 2px 6px rgba(27, 27, 31, 0.06), 0 12px 40px rgba(27, 27, 31, 0.1);\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 14px;\n  --font-display: \"Fraunces\", \"Noto Serif SC\", \"Songti SC\", serif;\n  --font-ui: \"Instrument Sans\", \"Noto Sans SC\", \"PingFang SC\", ui-sans-serif, system-ui, sans-serif;\n  --font-mono: \"JetBrains Mono\", ui-monospace, SFMono-Regular, Menlo, monospace;\n\n  color: var(--text);\n  background: var(--bg);\n  font-family: var(--font-ui);\n  font-size: 15px;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]) {\n    --bg: #131418;\n    --surface: #1C1E24;\n    --sidebar-bg: #17191F;\n    --text: #E8E8EA;\n    --text-muted: #9A9AA2;\n    --text-faint: #63666E;\n    --border: #2A2C33;\n    --border-strong: #383B44;\n    --accent: #7B8CFF;\n    --accent-soft: #23273A;\n    --accent-ink: #A5B2FF;\n    --approval: #D9A441;\n    --approval-bg: #2A2415;\n    --approval-border: #453A1E;\n    --success: #5FBE85;\n    --error: #E06A5B;\n    --error-bg: #33201D;\n    --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.25);\n    --shadow-hover: 0 1px 3px rgba(0, 0, 0, 0.25), 0 6px 24px rgba(0, 0, 0, 0.32);\n    --shadow-pop: 0 2px 6px rgba(0, 0, 0, 0.3), 0 12px 40px rgba(0, 0, 0, 0.4);\n  }\n}\n\nhtml[data-theme=\"dark\"] {\n  --bg: #131418;\n  --surface: #1C1E24;\n  --sidebar-bg: #17191F;\n  --text: #E8E8EA;\n  --text-muted: #9A9AA2;\n  --text-faint: #63666E;\n  --border: #2A2C33;\n  --border-strong: #383B44;\n  --accent: #7B8CFF;\n  --accent-soft: #23273A;\n  --accent-ink: #A5B2FF;\n  --approval: #D9A441;\n  --approval-bg: #2A2415;\n  --approval-border: #453A1E;\n  --success: #5FBE85;\n  --error: #E06A5B;\n  --error-bg: #33201D;\n  --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.25);\n  --shadow-hover: 0 1px 3px rgba(0, 0, 0, 0.25), 0 6px 24px rgba(0, 0, 0, 0.32);\n  --shadow-pop: 0 2px 6px rgba(0, 0, 0, 0.3), 0 12px 40px rgba(0, 0, 0, 0.4);\n}\n\nhtml[data-theme=\"light\"] {\n  --bg: #FAFAF8;\n  --surface: #FFFFFF;\n  --sidebar-bg: #F4F3EF;\n  --text: #1B1B1F;\n  --text-muted: #6E6E73;\n  --text-faint: #9B9BA0;\n  --border: #E6E4DE;\n  --border-strong: #D8D5CC;\n  --accent: #3A4ED0;\n  --accent-soft: #EEF0FC;\n  --accent-ink: #2C3DA8;\n  --approval: #B7791F;\n  --approval-bg: #FDF8EC;\n  --approval-border: #EADFC2;\n  --success: #2F7D4F;\n  --error: #B3382C;\n  --error-bg: #FBEEEC;\n  --shadow-card: 0 1px 2px rgba(27, 27, 31, 0.04), 0 4px 16px rgba(27, 27, 31, 0.05);\n  --shadow-hover: 0 1px 3px rgba(27, 27, 31, 0.06), 0 6px 24px rgba(27, 27, 31, 0.08);\n  --shadow-pop: 0 2px 6px rgba(27, 27, 31, 0.06), 0 12px 40px rgba(27, 27, 31, 0.1);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml,\nbody,\n#root {\n  margin: 0;\n  height: 100%;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--text);\n}\n\nbutton,\ninput,\ntextarea {\n  font: inherit;\n}\n\nbutton {\n  color: inherit;\n}\n\n/* ---- 窗口标题栏（overlay 交通灯区域） ---- */\n\n.titlebar {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  height: 44px;\n  /* 左右共用同一内边距，两侧收起按钮到窗口边框的距离始终相等。\n     交通灯与 Windows 标题按钮在上方拖拽条，不占用本行。 */\n  padding-inline: 14px;\n  background: var(--sidebar-bg);\n  border-bottom: 1px solid var(--border);\n  user-select: none;\n  flex-shrink: 0;\n  min-width: 0;\n}\n\n.titlebar-title {\n  flex: 1;\n  min-width: 0;\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text-muted);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.nav-toggle,\n.right-toggle {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-muted);\n  width: 34px;\n  height: 34px;\n  border-radius: var(--radius-sm);\n  display: grid;\n  place-items: center;\n  cursor: pointer;\n  flex-shrink: 0;\n  -webkit-app-region: no-drag;\n}\n\n.nav-toggle:hover,\n.right-toggle:hover {\n  background: color-mix(in srgb, var(--text) 7%, transparent);\n  color: var(--text);\n}\n\n.huaan-no-drag {\n  -webkit-app-region: no-drag;\n}\n\n/* ---- 整体布局 ---- */\n\n.app-shell {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n.shell {\n  display: grid;\n  grid-template-columns: 240px minmax(0, 1fr) 360px;\n  flex: 1;\n  min-height: 0;\n  transition: grid-template-columns 300ms ease-out;\n}\n\n.shell.no-right {\n  grid-template-columns: 240px minmax(0, 1fr);\n}\n\n.shell.collapsed {\n  grid-template-columns: 52px minmax(0, 1fr) 360px;\n}\n\n.shell.collapsed.no-right {\n  grid-template-columns: 52px minmax(0, 1fr);\n}\n\n/* 右侧面板收起：保持三列轨道，第三列 360px → 0 才能平滑过渡 */\n\n.shell.right-collapsed {\n  grid-template-columns: 240px minmax(0, 1fr) 0px;\n}\n\n.shell.collapsed.right-collapsed {\n  grid-template-columns: 52px minmax(0, 1fr) 0px;\n}\n\n/* ---- 左侧导航 ---- */\n\n.sidebar {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  background: var(--sidebar-bg);\n  border-right: 1px solid var(--border);\n  color: var(--text);\n  padding: 10px;\n  gap: 4px;\n  overflow: hidden;\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 2px 6px 10px;\n  font-weight: 700;\n  font-size: 13px;\n}\n\n.brand img {\n  width: 20px;\n  height: 20px;\n  border-radius: 5px;\n  flex-shrink: 0;\n}\n\n.nav-it {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  padding: 6px 8px;\n  border-radius: 7px;\n  color: var(--text);\n  font-size: 12.5px;\n  cursor: pointer;\n  text-align: left;\n}\n\n.nav-it svg {\n  flex-shrink: 0;\n  opacity: 0.7;\n}\n\n.nav-it:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.nav-it.on {\n  background: color-mix(in srgb, var(--text) 7%, transparent);\n  font-weight: 600;\n}\n\n.nav-it.on svg {\n  opacity: 1;\n}\n\n.nav-it .kbd {\n  margin-left: auto;\n  font-family: var(--font-mono);\n  font-size: 10px;\n  color: var(--text-faint);\n}\n\n.side-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 13.5px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  color: var(--text);\n  padding: 12px 8px 6px;\n  margin-bottom: 2px;\n  border-bottom: 1px solid var(--border);\n  text-transform: none;\n}\n\n.side-action {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-muted);\n  cursor: pointer;\n  font-size: 11px;\n  font-weight: 500;\n  padding: 2px 4px;\n  border-radius: 4px;\n  letter-spacing: 0;\n  text-transform: none;\n}\n\n.side-action:hover {\n  background: color-mix(in srgb, var(--text) 7%, transparent);\n  color: var(--text);\n}\n\n.side-section {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  gap: 4px;\n}\n\n.workspace-section {\n  flex: 1 1 auto;\n  overflow: hidden;\n}\n\n.recent-section {\n  flex: 0 1 auto;\n  max-height: 34%;\n  overflow: hidden;\n}\n\n.side-muted {\n  color: var(--text-faint);\n  font-size: 11.5px;\n  margin: 4px 8px;\n}\n\n.workspace-path {\n  font-size: 11px;\n  color: var(--text-muted);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  padding: 0 8px;\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n\n.side-tree {\n  overflow: auto;\n  min-height: 0;\n  border-radius: var(--radius-md);\n  background: color-mix(in srgb, var(--text) 3%, transparent);\n  padding: 6px;\n}\n\n.tree-root {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 4px;\n  padding: 2px 4px 4px;\n}\n\n.tree-root-name {\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.tree-toggle {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-faint);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 2px;\n  border-radius: 4px;\n  cursor: pointer;\n  flex-shrink: 0;\n}\n\n.tree-toggle:hover {\n  color: var(--accent);\n  background: color-mix(in srgb, var(--accent) 10%, transparent);\n}\n\n.sidebar .tree {\n  list-style: none;\n  margin: 0;\n  padding: 0 0 4px 6px;\n  font-size: 12.5px;\n}\n\n.sidebar .tree ul {\n  padding-left: 14px;\n}\n\n.sidebar .tree summary {\n  cursor: pointer;\n  color: var(--text);\n  padding: 1px 4px;\n}\n\n.sidebar .file-link {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  padding: 2px 6px;\n  margin: 0;\n  cursor: pointer;\n  text-align: left;\n  color: var(--text-muted);\n  border-radius: 4px;\n  width: calc(100% - 8px);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* 右侧面板「项目」页签的文件树（视觉与左侧边栏树一致） */\n\n.project-tree-card {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n}\n\n.project-tree-card .side-tree {\n  flex: 1;\n}\n\n.right-pane .tree {\n  list-style: none;\n  margin: 0;\n  padding: 0 0 4px 6px;\n  font-size: 12.5px;\n}\n\n.right-pane .tree ul {\n  list-style: none;\n  margin: 0;\n  padding-left: 14px;\n}\n\n.right-pane .tree summary {\n  cursor: pointer;\n  color: var(--text);\n  padding: 1px 4px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.right-pane .tree-file,\n.right-pane .tree-dir-empty {\n  display: block;\n  padding: 2px 6px;\n  margin: 0;\n  text-align: left;\n  border-radius: 4px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.right-pane .tree-file {\n  color: var(--text-muted);\n}\n\n.right-pane .tree-dir-empty {\n  color: var(--text-faint);\n}\n\n.sidebar .file-link:hover,\n.sidebar .file-link.active {\n  background: color-mix(in srgb, var(--text) 7%, transparent);\n  color: var(--text);\n}\n\n.recent-list {\n  list-style: none;\n  margin: 0;\n  padding: 0 2px;\n  overflow: auto;\n  min-height: 0;\n}\n\n.recent-item {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-muted);\n  cursor: pointer;\n  display: block;\n  width: 100%;\n  text-align: left;\n  padding: 6px 8px;\n  border-radius: 6px;\n  overflow: hidden;\n  position: relative;\n}\n\n.recent-item:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.recent-title {\n  display: block;\n  font-size: 12.5px;\n  color: var(--text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.recent-meta {\n  display: block;\n  margin-top: 2px;\n  font-size: 11px;\n  color: var(--text-faint);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.recent-item.live-dot .recent-title,\n.recent-item.live-dot .recent-meta {\n  padding-right: 14px;\n}\n\n.recent-item.live-dot::after {\n  content: \"●\";\n  color: var(--approval);\n  font-size: 8px;\n  position: absolute;\n  right: 8px;\n  top: 50%;\n  transform: translateY(-50%);\n}\n\n.side-footer {\n  margin-top: auto;\n  border-top: 1px solid var(--border);\n  padding-top: 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.user-row {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 6px;\n  border-radius: 8px;\n  cursor: pointer;\n  color: var(--text);\n  text-align: left;\n  width: 100%;\n}\n\n.user-row:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.user-row .avatar {\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, var(--accent), var(--accent-ink));\n  color: #fff;\n  display: grid;\n  place-items: center;\n  font-size: 10px;\n  font-weight: 700;\n  flex-shrink: 0;\n}\n\n.user-row .uname {\n  font-size: 12px;\n  font-weight: 600;\n}\n\n.user-row .ustate {\n  margin-left: auto;\n  font-size: 10.5px;\n  color: var(--text-faint);\n}\n\n.user-row .ustate.tone-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  font-size: 0;\n  line-height: 0;\n  color: transparent;\n  flex-shrink: 0;\n}\n\n.tone-dot.tone-ok,\n.sidecar-badge.tone-ok {\n  background: var(--success);\n}\n\n.tone-dot.tone-wait,\n.sidecar-badge.tone-wait {\n  background: var(--approval);\n}\n\n.tone-dot.tone-dead,\n.sidecar-badge.tone-dead {\n  background: var(--error);\n}\n\n.sidecar-badge {\n  display: none;\n}\n\n.foot-meta {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 11.5px;\n  color: var(--text-muted);\n}\n\n.side-link {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-muted);\n  cursor: pointer;\n  padding: 4px 6px;\n  border-radius: 6px;\n  font-size: 11.5px;\n}\n\n.side-link:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n  color: var(--text);\n}\n\n.status-dot {\n  font-size: 11px;\n  color: var(--approval);\n}\n\n.status-dot.ok {\n  color: var(--success);\n}\n\n/* 收起态：48px 图标栏 */\n\n.shell.collapsed .sidebar {\n  padding: 10px 6px;\n  align-items: center;\n}\n\n.shell.collapsed .brand span,\n.shell.collapsed .nav-it .lbl,\n.shell.collapsed .nav-it .kbd,\n.shell.collapsed .side-section,\n.shell.collapsed .foot-meta,\n.shell.collapsed .user-row .uname,\n.shell.collapsed .user-row .ustate {\n  display: none;\n}\n\n.shell.collapsed .nav-it {\n  justify-content: center;\n  padding: 7px 0;\n  width: 36px;\n}\n\n.shell.collapsed .nav-it svg {\n  opacity: 1;\n}\n\n.shell.collapsed .user-row {\n  justify-content: center;\n  padding: 4px 0;\n  width: 36px;\n}\n\n.shell.collapsed .user-row .avatar {\n  position: relative;\n}\n\n.shell.collapsed .user-row .avatar .sidecar-badge {\n  display: block;\n  position: absolute;\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  right: -1px;\n  bottom: -1px;\n  box-shadow: 0 0 0 1.5px var(--sidebar-bg);\n}\n\n/* ---- 中间主区 ---- */\n\n.main {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  min-width: 0;\n  background: var(--bg);\n}\n\n.muted {\n  color: var(--text-muted);\n}\n\n.pad {\n  padding: 12px;\n}\n\n.banner {\n  padding: 8px 14px;\n  font-size: 13.5px;\n  border-bottom: 1px solid var(--border);\n}\n\n.banner.warn {\n  background: var(--approval-bg);\n  color: var(--approval);\n}\n\n.banner.error {\n  background: var(--error-bg);\n  color: var(--error);\n}\n\n.missed-banner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  border-radius: 10px;\n  margin-bottom: 12px;\n}\n\n.tab-bar {\n  display: flex;\n  align-items: stretch;\n  gap: 2px;\n  min-height: 38px;\n  padding: 0 8px;\n  overflow-x: auto;\n  border-bottom: 1px solid var(--border);\n  background: var(--surface);\n}\n\n.tab-item {\n  display: flex;\n  align-items: center;\n  max-width: 180px;\n  flex-shrink: 0;\n}\n\n.tab {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  padding: 9px 10px;\n  cursor: pointer;\n  color: var(--text-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tab-item .tab {\n  padding-right: 2px;\n  max-width: 140px;\n}\n\n.tab.active,\n.tab-item.active .tab {\n  color: var(--text);\n  font-weight: 600;\n  box-shadow: inset 0 -2px 0 var(--accent);\n}\n\n.tab-close {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  padding: 0 8px 0 4px;\n  cursor: pointer;\n  color: var(--text-faint);\n}\n\n.tab-close:hover {\n  color: var(--text);\n}\n\n.chat-log {\n  flex: 1;\n  overflow: auto;\n  padding: 16px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n\n/* 空态 hero */\n\n.hero {\n  margin: auto;\n  text-align: center;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  align-items: center;\n  padding: 24px;\n}\n\n.hero h1 {\n  margin: 0;\n  font-family: var(--font-display);\n  font-size: 44px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  line-height: 1.15;\n}\n\n.hero h1 em {\n  font-style: italic;\n  color: var(--accent);\n}\n\n.hero p {\n  margin: 0;\n  color: var(--text-muted);\n}\n\n.hero-suggestions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n  justify-content: center;\n  margin-top: 10px;\n}\n\n/* 消息 */\n\n.bubble {\n  max-width: 82%;\n  padding: 9px 12px;\n  border-radius: 12px;\n  white-space: pre-wrap;\n  line-height: 1.6;\n}\n\n.bubble.user {\n  align-self: flex-end;\n  background: var(--sidebar-bg);\n  border: 1px solid var(--border);\n}\n\n.bubble.assistant {\n  align-self: flex-start;\n  background: transparent;\n  border: 0;\n  padding: 2px 0;\n  max-width: 88%;\n  line-height: 1.7;\n}\n\n.note {\n  color: var(--text-muted);\n  font-size: 12px;\n}\n\n.thinking-body {\n  max-height: 40vh;\n  overflow: auto;\n  white-space: pre-wrap;\n  color: var(--text-muted);\n}\n\n/* 工具调用 pill */\n\n.tool-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  align-self: flex-start;\n  padding: 4px 12px;\n  border: 1px solid var(--border);\n  border-radius: 999px;\n  background: var(--surface);\n  font-size: 12px;\n  color: var(--text-muted);\n}\n\n.tool-row.running {\n  border-color: var(--border-strong);\n}\n\n.tool-row.running .tool-icon {\n  color: var(--accent);\n  animation: tool-pulse 1.4s ease-in-out infinite;\n}\n\n@keyframes tool-pulse {\n  50% {\n    opacity: 0.35;\n  }\n}\n\n.tool-icon {\n  font-size: 11px;\n  color: var(--success);\n}\n\n.badge {\n  display: inline-block;\n  background: color-mix(in srgb, var(--text) 8%, transparent);\n  color: var(--text-muted);\n  padding: 1px 6px;\n  border-radius: 4px;\n  font-size: 11px;\n}\n\n/* 结果附件（规格 §4.1 / §5）：折叠后的 JSON 结果只留两个入口 */\n\n.attachment-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-self: flex-start;\n}\n\n.attachment-file {\n  appearance: none;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  color: var(--text);\n  border-radius: var(--radius-sm);\n  padding: 6px 12px;\n  font-family: var(--font-mono);\n  font-size: 12.5px;\n  cursor: pointer;\n}\n\n.attachment-file:hover {\n  border-color: var(--accent);\n  background: var(--accent-soft);\n  color: var(--accent-ink, var(--accent));\n}\n\n.attachment-file:focus-visible {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n  outline: none;\n}\n\n/* 审批卡（琥珀色 = agent 要动你的东西） */\n\n.card {\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-lg);\n  padding: 12px 14px;\n  background: var(--surface);\n}\n\n.ask-card {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  align-self: stretch;\n  border-color: var(--approval-border);\n  background: var(--approval-bg);\n}\n\n.ask-card .ttl {\n  font-weight: 700;\n  color: var(--approval);\n  font-size: 12.5px;\n}\n\n.ask-card pre {\n  margin: 0;\n  padding: 8px 10px;\n  background: color-mix(in srgb, var(--approval) 7%, var(--surface));\n  border-radius: 8px;\n  overflow: auto;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n}\n\n.ask-card .muted {\n  font-family: var(--font-mono);\n  font-size: 11px;\n}\n\n.btn {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  border-radius: 999px;\n  padding: 8px 18px;\n  font-size: 13.5px;\n  font-weight: 600;\n  cursor: pointer;\n  background: var(--surface);\n  color: var(--text);\n}\n\n.btn.primary {\n  background: var(--accent);\n  border-color: transparent;\n  color: #fff;\n}\n\n.btn.primary:hover {\n  background: var(--accent-ink);\n}\n\n.btn.approve {\n  background: var(--approval);\n  border-color: transparent;\n  color: #fff;\n}\n\n.btn.reject {\n  background: transparent;\n  border-color: var(--approval-border);\n  color: var(--approval);\n}\n\n.btn.danger {\n  background: var(--error);\n  border-color: transparent;\n  color: #fff;\n}\n\n.btn:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n/* 输入框（浮动卡片 composer）— work / chat 统一风格：\n   宽度按主区百分比自适应并居中，主区宽度变化（导航/右侧面板收起）时\n   随 grid 过渡平滑重排 */\n\n.composer {\n  position: relative;\n  margin: clamp(8px, 1.5vh, 14px) auto clamp(10px, 2vh, 18px);\n  max-width: 640px;\n  width: calc(100% - clamp(24px, 6vw, 64px));\n  border: 1px solid var(--border-strong);\n  border-radius: 16px;\n  background: var(--surface);\n  box-shadow: var(--shadow-card);\n  display: flex;\n  flex-direction: column;\n  transition: border-color 160ms ease-out, box-shadow 200ms ease-out;\n}\n\n.composer:hover {\n  border-color: color-mix(in srgb, var(--accent) 40%, var(--border-strong));\n  box-shadow: var(--shadow-hover);\n}\n\n.composer:focus-within {\n  border-color: var(--accent);\n  box-shadow: var(--shadow-hover), 0 0 0 3px var(--accent-soft);\n}\n\n.slash-menu {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: calc(100% + 8px);\n  max-height: 280px;\n  overflow: auto;\n  border: 1px solid var(--border-strong);\n  border-radius: 10px;\n  background: var(--surface);\n  box-shadow: var(--shadow-card);\n  z-index: 5;\n}\n\n.slash-empty {\n  padding: 12px 14px;\n  color: var(--text-faint);\n  font-size: 13.5px;\n}\n\n.slash-item {\n  appearance: none;\n  display: grid;\n  grid-template-columns: minmax(0, auto) auto;\n  grid-template-rows: auto auto;\n  column-gap: 8px;\n  row-gap: 2px;\n  width: 100%;\n  border: 0;\n  background: transparent;\n  text-align: left;\n  padding: 8px 14px;\n  cursor: pointer;\n  color: var(--text);\n}\n\n.slash-item.on,\n.slash-item:hover {\n  background: var(--accent-soft);\n}\n\n.slash-item-name {\n  font-weight: 700;\n  font-size: 13.5px;\n}\n\n.slash-item-src {\n  justify-self: end;\n  color: var(--text-faint);\n  font-size: 11px;\n}\n\n.slash-item-desc {\n  grid-column: 1 / -1;\n  color: var(--text-muted);\n  font-size: 12.5px;\n  line-height: 1.4;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n\n.composer textarea {\n  appearance: none;\n  border: 0;\n  outline: none;\n  resize: none;\n  padding: 12px 16px 4px;\n  background: transparent;\n  line-height: 1.5;\n  color: var(--text);\n  height: clamp(56px, 12vh, 148px);\n}\n\n.composer-bar {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 12px 10px;\n}\n\n.chip {\n  appearance: none;\n  border: 1px solid var(--border);\n  background: var(--sidebar-bg);\n  color: var(--text-muted);\n  border-radius: 999px;\n  padding: 3px 10px;\n  font-size: 12px;\n  cursor: pointer;\n  max-width: 200px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.chip:hover {\n  border-color: var(--accent);\n  color: var(--accent);\n}\n\n.chip.static {\n  cursor: default;\n  color: var(--approval);\n  background: var(--approval-bg);\n  border-color: var(--approval-border);\n}\n\n.chip.static:hover {\n  color: var(--approval);\n  border-color: var(--approval-border);\n}\n\n.chip.pick {\n  color: var(--accent);\n  background: var(--accent-soft);\n  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));\n}\n\n.chip.pick:hover {\n  color: var(--accent-ink, var(--accent));\n  border-color: var(--accent);\n}\n\n.composer-spacer {\n  flex: 1;\n}\n\n.send {\n  appearance: none;\n  border: 0;\n  border-radius: 50%;\n  width: 30px;\n  height: 30px;\n  background: var(--accent);\n  color: #fff;\n  cursor: pointer;\n  display: grid;\n  place-items: center;\n  font-size: 14px;\n  flex-shrink: 0;\n}\n\n.send:hover:not(:disabled) {\n  background: var(--accent-ink);\n}\n\n.send:disabled {\n  background: var(--border-strong);\n  cursor: default;\n}\n\n.send.stop:not(:disabled) {\n  background: var(--error);\n  border-radius: 8px;\n  font-size: 12px;\n  width: auto;\n  height: auto;\n  padding: 6px 16px;\n  font-weight: 600;\n}\n\n/* 文件预览 */\n\n.file-view {\n  flex: 1;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  background: var(--surface);\n}\n\n.file-meta {\n  padding: 6px 12px;\n  border-bottom: 1px solid var(--border);\n  font-size: 12px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.file-content {\n  flex: 1;\n  margin: 0;\n  padding: 12px;\n  overflow: auto;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n/* ---- 右侧面板（进度 / 上下文 / 变更） ---- */\n\n.right-pane {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  min-width: 0;\n  border-left: 1px solid var(--border);\n  background: var(--sidebar-bg);\n  overflow: hidden;\n}\n\n.shell.right-collapsed .right-pane {\n  border-left-color: transparent;\n  background: transparent;\n}\n\n.shell.right-collapsed .right-tabs,\n.shell.right-collapsed .right-body {\n  visibility: hidden;\n}\n\n.right-tabs {\n  display: flex;\n  gap: 14px;\n  padding: 10px 14px 0;\n  border-bottom: 1px solid var(--border);\n}\n\n.right-tabs button {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  padding: 0 0 8px;\n  font-size: 12.5px;\n  color: var(--text-muted);\n  cursor: pointer;\n  position: relative;\n}\n\n.right-tabs button.on {\n  color: var(--text);\n  font-weight: 700;\n  box-shadow: inset 0 -2px 0 var(--accent);\n}\n\n.right-tabs .dot::after {\n  content: \"●\";\n  color: var(--approval);\n  font-size: 7px;\n  position: absolute;\n  top: 0;\n  right: -9px;\n}\n\n.right-body {\n  flex: 1;\n  overflow: auto;\n  padding: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.panel-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 12px;\n}\n\n.panel-card .h {\n  font-weight: 700;\n  font-size: 12px;\n  margin: 0 0 8px;\n}\n\n.panel-empty {\n  color: var(--text-faint);\n  font-size: 12px;\n  text-align: center;\n  padding: 24px 8px;\n}\n\n/* 结果附件预览（规格 §5）：卡片撑满右栏；Markdown 横向滚动，HTML 用 sandbox iframe */\n\n.preview-card {\n  display: flex;\n  flex-direction: column;\n  flex: 1 1 auto;\n  min-height: 0;\n}\n\n.preview-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  font-family: var(--font-mono);\n}\n\n.preview-md {\n  flex: 1 1 auto;\n  min-height: 0;\n  margin: 0;\n  padding: 10px 12px;\n  overflow: auto;\n  white-space: pre;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  line-height: 1.55;\n  color: var(--text);\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n}\n\n.preview-frame {\n  display: block;\n  flex: 1 1 auto;\n  min-height: 0;\n  width: 100%;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n}\n\n.ctx-file {\n  display: flex;\n  gap: 6px;\n  align-items: center;\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  color: var(--text-muted);\n  padding: 3px 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.diff {\n  flex: 1;\n  margin: 0;\n  overflow: auto;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 10px 12px;\n  min-height: 0;\n}\n\n/* ---- 技能中心 / 定时任务页 ---- */\n\n.page-view {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 24px 28px;\n  background: var(--bg);\n}\n\n.page-head {\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.page-head h1 {\n  font-family: var(--font-display);\n  font-size: 30px;\n  font-weight: 600;\n  margin: 0;\n}\n\n.page-head .hint-text {\n  font-size: 13px;\n  color: var(--text-muted);\n}\n\n.page-tools {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  margin: 16px 0 20px;\n  flex-wrap: wrap;\n}\n\n.search-input {\n  appearance: none;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  border-radius: 999px;\n  padding: 6px 14px;\n  font-size: 13px;\n  color: var(--text);\n  width: 220px;\n  outline: none;\n}\n\n.search-input:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.filter-tab {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  font-size: 12.5px;\n  color: var(--text-muted);\n  cursor: pointer;\n  padding: 4px 10px;\n  border-radius: 999px;\n}\n\n.filter-tab.on {\n  background: color-mix(in srgb, var(--text) 7%, transparent);\n  color: var(--text);\n  font-weight: 600;\n}\n\n.btn-dark {\n  appearance: none;\n  border: 0;\n  background: var(--text);\n  color: var(--bg);\n  border-radius: 8px;\n  padding: 7px 14px;\n  font-size: 12.5px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n/* ---- 智能体页公用机配置条 ---- */\n\n.agents-config-bar {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-start;\n  gap: 8px;\n  margin: 12px 0 16px;\n}\n\n.agents-config-bar .filter-tab {\n  height: 28px;\n  padding: 0 12px;\n  display: inline-flex;\n  align-items: center;\n}\n\n.agents-config-bar .filter-tab:disabled {\n  opacity: 0.6;\n  cursor: not-allowed;\n}\n\n.agents-config-field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.agents-config-input {\n  appearance: none;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  border-radius: var(--radius-sm);\n  padding: 5px 10px;\n  font-size: 12.5px;\n  color: var(--text);\n  outline: none;\n  box-sizing: border-box;\n  height: 28px;\n}\n\n.agents-config-input:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 2px var(--accent-soft);\n}\n\n.agents-field-error {\n  font-size: 11px;\n  color: var(--error);\n  padding-left: 2px;\n}\n\n.skill-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\n  gap: 12px;\n}\n\n.skill-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 14px 16px;\n}\n\n.skill-card .top {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  margin-bottom: 8px;\n}\n\n.skill-card .av {\n  width: 28px;\n  height: 28px;\n  border-radius: 7px;\n  background: var(--accent-soft);\n  color: var(--accent);\n  display: grid;\n  place-items: center;\n  font-weight: 700;\n  font-size: 12px;\n  flex-shrink: 0;\n}\n\n.skill-card .nm {\n  font-weight: 700;\n  font-size: 13.5px;\n  font-family: var(--font-mono);\n}\n\n.skill-card .src {\n  font-size: 11px;\n  color: var(--text-faint);\n}\n\n.skill-card p {\n  font-size: 12.5px;\n  color: var(--text-muted);\n  line-height: 1.55;\n  margin: 0;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n}\n\n/* ---- 智能体包三页签（Task 8） ---- */\n\n.agent-card-badges {\n  display: flex;\n  gap: 4px;\n  margin-top: 4px;\n  flex-wrap: wrap;\n  align-items: center;\n}\n\n.agent-update-hint {\n  margin-top: 6px;\n  font-size: 12px;\n}\n\n.agent-toolkit-group {\n  margin: 4px 0 10px;\n  font-size: 13px;\n  color: var(--text-muted);\n}\n\n.agent-detail-section {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-size: 12.5px;\n}\n\n.agent-detail-section p {\n  margin: 0;\n  color: var(--text-muted);\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.agent-detail-section pre {\n  margin: 0;\n  padding: 8px 10px;\n  background: color-mix(in srgb, var(--text) 4%, transparent);\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 180px;\n  overflow: auto;\n}\n\n.agent-detail-section ul {\n  margin: 0;\n  padding-left: 18px;\n  color: var(--text-muted);\n}\n\n.agent-confirm-card {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  align-self: stretch;\n  border-color: var(--approval-border);\n  background: var(--approval-bg);\n}\n\n.agent-confirm-card .ttl {\n  font-weight: 700;\n  color: var(--approval);\n  font-size: 12.5px;\n}\n\n.agent-confirm-rows {\n  display: grid;\n  gap: 6px;\n  margin: 0;\n}\n\n.agent-confirm-row {\n  display: grid;\n  grid-template-columns: 52px minmax(0, 1fr);\n  gap: 8px;\n  font-size: 12.5px;\n}\n\n.agent-confirm-row dt {\n  color: var(--text-muted);\n}\n\n.agent-confirm-row dd {\n  margin: 0;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n/* 空状态页（定时任务） */\n\n.empty-state {\n  display: grid;\n  place-items: center;\n  min-height: 55vh;\n  text-align: center;\n  color: var(--text-muted);\n}\n\n.empty-state .art {\n  color: var(--border-strong);\n  margin-bottom: 16px;\n}\n\n.empty-state p {\n  margin: 0 0 6px;\n  font-size: 14px;\n}\n\n.empty-state .sub {\n  font-size: 12.5px;\n  color: var(--text-faint);\n}\n\n/* ---- 弹层 ---- */\n\n.settings-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.35);\n  display: grid;\n  place-items: center;\n  z-index: 10;\n}\n\n.settings-panel,\n.confirm-modal {\n  width: min(480px, 92vw);\n  background: var(--surface);\n  color: var(--text);\n  padding: 16px;\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-pop);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.settings-panel.settings-wide {\n  width: min(640px, 92vw);\n  flex-direction: column;\n}\n\n.settings-body {\n  display: grid;\n  grid-template-columns: 140px minmax(0, 1fr);\n  gap: 16px;\n  min-height: 280px;\n}\n\n.settings-nav {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.settings-nav button {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  width: 100%;\n  padding: 6px 8px;\n  border-radius: var(--radius-sm);\n  color: var(--text);\n  font-size: 12.5px;\n  cursor: pointer;\n  text-align: left;\n}\n\n.settings-nav button.on {\n  background: var(--accent-soft);\n  color: var(--accent);\n}\n\n.settings-pane {\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  max-height: min(70vh, 560px);\n  overflow: auto;\n}\n\n.settings-pane form {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.account-username {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin: 0;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.account-username span {\n  color: var(--text);\n}\n\n.theme-seg {\n  display: flex;\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n  border-radius: var(--radius-sm);\n  padding: 2px;\n}\n\n.theme-seg button {\n  appearance: none;\n  border: 0;\n  flex: 1;\n  padding: 6px 8px;\n  border-radius: var(--radius-sm);\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--text-muted);\n  background: transparent;\n  cursor: pointer;\n}\n\n.theme-seg button.on {\n  background: var(--accent);\n  color: var(--surface);\n}\n\n.settings-panel label {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.settings-panel input:not([type=\"checkbox\"]):not([type=\"radio\"]) {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--text);\n  padding: 9px 12px;\n  font-size: 14px;\n  outline: none;\n  font-weight: 400;\n}\n\n.settings-panel input:not([type=\"checkbox\"]):not([type=\"radio\"]):focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.settings-panel .perm-row {\n  flex-direction: row;\n}\n\n.settings-panel h2,\n.settings-panel h3 {\n  margin: 0;\n}\n\n.pane-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 0;\n  border-bottom: 0;\n  font-weight: 600;\n}\n\n.pane-header button {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  background: transparent;\n  color: var(--text-muted);\n  border-radius: 999px;\n  padding: 4px 12px;\n  font-size: 12px;\n  cursor: pointer;\n}\n\n.session-log-panel {\n  width: min(720px, 92vw);\n  max-height: 84vh;\n}\n\n.session-log {\n  margin: 0;\n  overflow: auto;\n  min-height: 0;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n/* 会话详情（session.open 的结构化记录视图） */\n\n.session-detail-title {\n  font-size: 15px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.detail-meta {\n  display: flex;\n  flex-wrap: wrap;\n  margin: 0;\n  font-size: 11.5px;\n  color: var(--text-faint);\n}\n\n.detail-meta span {\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  min-width: 0;\n}\n\n.detail-meta span + span::before {\n  content: \"·\";\n  margin: 0 6px;\n}\n\n.session-detail {\n  margin: 0;\n  overflow: auto;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 2px 4px 2px 0;\n}\n\n.detail-row {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  min-width: 0;\n}\n\n.detail-role {\n  font-size: 11px;\n  color: var(--text-faint);\n}\n\n.detail-bubble {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n  border-radius: var(--radius-md);\n  padding: 8px 12px;\n  font-size: 13.5px;\n  color: var(--text);\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.detail-body {\n  font-size: 13.5px;\n  color: var(--text);\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n.detail-tool {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  font-family: var(--font-mono);\n  font-size: 12px;\n  color: var(--text-muted);\n  min-width: 0;\n}\n\n.detail-tool-mark {\n  color: var(--text-faint);\n}\n\n.detail-tool-name {\n  color: var(--text);\n  font-weight: 600;\n}\n\n.detail-tool-args {\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  color: var(--text-faint);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.detail-result summary {\n  cursor: pointer;\n  font-size: 12px;\n  color: var(--text-muted);\n  list-style: none;\n  display: flex;\n  gap: 6px;\n  align-items: baseline;\n}\n\n.detail-result summary::-webkit-details-marker {\n  display: none;\n}\n\n.detail-result summary::before {\n  content: \"▸\";\n  color: var(--text-faint);\n  transition: transform 80ms ease-out;\n}\n\n.detail-result[open] summary::before {\n  transform: rotate(90deg);\n}\n\n.detail-result summary.err {\n  color: var(--error);\n}\n\n.detail-result pre {\n  margin: 6px 0 0 14px;\n  padding: 8px 10px;\n  background: var(--sidebar-bg);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n  font-size: 12px;\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 260px;\n  overflow: auto;\n}\n\n.row {\n  display: flex;\n  gap: 8px;\n}\n\n.model-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.model-card {\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--surface);\n  padding: 10px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.model-card.on {\n  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));\n  background: var(--accent-soft);\n}\n\n.model-card-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 8px;\n}\n\n.model-card-name {\n  font-size: 13.5px;\n  font-weight: 700;\n}\n\n.model-card-meta {\n  margin-top: 2px;\n  font-size: 12px;\n  color: var(--text-muted);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.model-badge {\n  flex-shrink: 0;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--accent);\n}\n\n.model-form {\n  padding-top: 4px;\n  border-top: 1px solid var(--border);\n}\n\n.model-card .row button,\n.model-form .row button,\n.settings-pane > button {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  background: transparent;\n  color: var(--text);\n  border-radius: 999px;\n  padding: 4px 12px;\n  font-size: 12px;\n  cursor: pointer;\n}\n\n.model-menu {\n  z-index: 20;\n  min-width: 196px;\n  max-height: min(50vh, 320px);\n  overflow: auto;\n}\n\n.context-menu-item.on {\n  background: var(--accent-soft);\n  color: var(--accent);\n}\n\n.plugin-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.plugin-list li {\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 4px 0;\n  font-size: 13px;\n}\n\n.hint,\n.status {\n  white-space: pre-wrap;\n  color: var(--text-muted);\n  font-size: 12.5px;\n  margin: 0;\n}\n\n.confirm-modal {\n  position: static; /* 由外层 .settings-overlay 居中；Settings 内单独使用时同样包在 overlay 里 */\n  z-index: 20;\n}\n\n/* 会话列表右键菜单 */\n\n.context-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 15;\n}\n\n.context-menu {\n  position: fixed;\n  min-width: 148px;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  box-shadow: var(--shadow-pop);\n  padding: 5px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.context-menu-item {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text);\n  text-align: left;\n  padding: 7px 10px;\n  border-radius: var(--radius-sm);\n  font-size: 13px;\n  cursor: pointer;\n}\n\n.context-menu-item:hover:not(:disabled) {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.context-menu-item.danger {\n  color: var(--error);\n}\n\n.context-menu-item.danger:hover:not(:disabled) {\n  background: var(--error-bg);\n}\n\n.context-menu-item:disabled,\n.context-menu-item[aria-disabled=\"true\"] {\n  color: var(--text-faint);\n  cursor: default;\n}\n\n.context-menu-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 16px;\n}\n\n.context-menu-item[aria-disabled=\"true\"]:hover {\n  background: transparent;\n}\n\n.context-menu-item .kbd {\n  font-size: 11px;\n  color: var(--text-faint);\n}\n\n.account-menu {\n  min-width: 220px;\n  z-index: 16;\n}\n\n.account-menu-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px 10px;\n  border-bottom: 1px solid var(--border);\n  margin-bottom: 2px;\n}\n\n.account-menu-head .avatar {\n  width: 22px;\n  height: 22px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, var(--accent), var(--accent-ink));\n  color: #fff;\n  display: grid;\n  place-items: center;\n  font-size: 10px;\n  font-weight: 700;\n  flex-shrink: 0;\n}\n\n.account-menu-name {\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.account-menu-status {\n  font-size: 11.5px;\n  color: var(--text-muted);\n}\n\n.auth-gate {\n  min-height: 100%;\n  display: grid;\n  place-items: center;\n  background: var(--bg);\n  padding: 32px 16px;\n}\n\n.auth-card {\n  width: min(360px, 100%);\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.auth-gate h1 {\n  margin: 0;\n  font-family: var(--font-display);\n  font-size: 30px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n}\n\n.auth-gate label {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.auth-gate input {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--text);\n  padding: 9px 12px;\n  font-size: 14px;\n  font-weight: 400;\n  outline: none;\n}\n\n.auth-gate input:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.auth-gate button[type=\"submit\"] {\n  appearance: none;\n  border: 0;\n  background: var(--accent);\n  color: #fff;\n  border-radius: var(--radius-sm);\n  padding: 10px 14px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.auth-gate button[type=\"submit\"]:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n\n.auth-sidecar {\n  margin: 0;\n  font-size: 12.5px;\n  color: var(--text-muted);\n}\n\n.auth-error {\n  margin: 0;\n  font-size: 12.5px;\n  color: var(--error);\n}\n\n/* ---- 项目（侧边栏项目区 / 项目选择弹层） ---- */\n\n.project-list {\n  list-style: none;\n  margin: 0;\n  padding: 0 2px;\n  overflow: auto;\n  min-height: 0;\n  max-height: 148px;\n  flex: 0 0 auto;\n}\n\n.project-item.active .recent-title {\n  color: var(--accent);\n  font-weight: 600;\n}\n\n.project-item.active .recent-meta {\n  color: var(--accent);\n  opacity: 0.75;\n}\n\n.project-card {\n  display: flex;\n  flex-direction: column;\n}\n\n.project-row {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n}\n\n.project-row .project-item {\n  flex: 1 1 auto;\n  min-width: 0;\n  width: auto;\n}\n\n.project-add-subtask {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-muted);\n  flex: 0 0 auto;\n  display: grid;\n  place-items: center;\n  width: 22px;\n  height: 22px;\n  margin-right: 4px;\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n.project-add-subtask:hover {\n  background: color-mix(in srgb, var(--accent) 12%, transparent);\n  color: var(--accent);\n}\n\n.project-add-subtask:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n.subtask-list {\n  list-style: none;\n  margin: 2px 0 4px;\n  padding: 0 2px 0 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.subtask-item {\n  font-size: 12px;\n  color: var(--text-muted);\n  padding: 3px 10px;\n  border-left: 2px solid color-mix(in srgb, var(--accent) 45%, transparent);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  appearance: none;\n  border-top: 0;\n  border-right: 0;\n  border-bottom: 0;\n  background: transparent;\n  cursor: pointer;\n  width: 100%;\n  text-align: left;\n  border-radius: 0 4px 4px 0;\n}\n\n.subtask-item:hover {\n  background: color-mix(in srgb, var(--accent) 10%, transparent);\n  color: var(--text);\n}\n\n.subtask-item.active {\n  color: var(--text);\n  border-left-color: var(--accent);\n  background: color-mix(in srgb, var(--accent) 14%, transparent);\n  font-weight: 500;\n}\n\n.subtask-item:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n/* 侧栏「任务」区子任务条目（可点击选中）。 */\n.side-task-item {\n  display: block;\n  padding: 6px 8px;\n  border-radius: 6px;\n  overflow: hidden;\n}\n\n.side-task-item.active {\n  background: color-mix(in srgb, var(--accent) 14%, transparent);\n}\n\n.side-task-item.active .recent-title {\n  color: var(--accent);\n  font-weight: 500;\n}\n\n/* 侧栏条目选中高亮（通用，用于自动化等可点击条目）。 */\n.recent-item.active {\n  background: color-mix(in srgb, var(--accent) 14%, transparent);\n}\n\n.recent-item.active .recent-title {\n  color: var(--accent);\n  font-weight: 500;\n}\n\n.side-error {\n  color: var(--error);\n  font-size: 11.5px;\n  margin: 2px 8px;\n  word-break: break-word;\n}\n\n.project-picker-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  max-height: 300px;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.picker-item {\n  appearance: none;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--text);\n  cursor: pointer;\n  display: block;\n  width: 100%;\n  text-align: left;\n  padding: 8px 10px;\n  border-radius: var(--radius-sm);\n}\n\n.picker-item:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.picker-item.active {\n  background: var(--accent-soft);\n  border-color: color-mix(in srgb, var(--accent) 24%, transparent);\n}\n\n.picker-item.active .recent-title {\n  color: var(--accent-ink);\n  font-weight: 600;\n}\n\n/* 新建任务选择器（关联到项目 / 添加到自动化） */\n\n.task-picker-section {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.task-picker-label {\n  margin: 0;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--text-muted);\n}\n\n.task-picker-automation {\n  appearance: none;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--text);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  text-align: left;\n  padding: 8px 10px;\n  border-radius: var(--radius-sm);\n}\n\n.task-picker-automation:hover {\n  background: color-mix(in srgb, var(--text) 6%, transparent);\n}\n\n.task-picker-automation:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n.task-picker-automation svg {\n  flex-shrink: 0;\n  color: var(--text-muted);\n}\n\n/* 全局轻提示（任务创建成功等反馈） */\n\n.toast {\n  position: fixed;\n  left: 50%;\n  bottom: 28px;\n  transform: translateX(-50%);\n  background: var(--surface);\n  color: var(--text);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  box-shadow: var(--shadow-pop);\n  padding: 8px 16px;\n  font-size: 13px;\n  max-width: min(480px, 86vw);\n  z-index: 60;\n  animation: toast-in 200ms ease-out;\n}\n\n@keyframes toast-in {\n  from {\n    opacity: 0;\n    transform: translate(-50%, 6px);\n  }\n  to {\n    opacity: 1;\n    transform: translate(-50%, 0);\n  }\n}\n\n/* ---- 自动化 ---- */\n\n.automation-tabs {\n  margin-bottom: 0;\n  flex: 0 0 auto;\n}\n\n.automation-tabs button {\n  padding: 4px 16px;\n}\n\n.project-select {\n  appearance: none;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  border-radius: 999px;\n  padding: 6px 30px 6px 14px;\n  font-size: 13px;\n  color: var(--text);\n  outline: none;\n  cursor: pointer;\n  background-image: linear-gradient(45deg, transparent 50%, var(--text-muted) 50%),\n    linear-gradient(135deg, var(--text-muted) 50%, transparent 50%);\n  background-position: calc(100% - 16px) 55%, calc(100% - 12px) 55%;\n  background-size: 4px 4px, 4px 4px;\n  background-repeat: no-repeat;\n}\n\n.project-select:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.automation-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  max-width: 860px;\n}\n\n.automation-row {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 10px 14px;\n}\n\n.automation-main {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-width: 0;\n}\n\n.automation-expand {\n  appearance: none;\n  border: 0;\n  background: transparent;\n  color: var(--text-faint);\n  cursor: pointer;\n  font-size: 11px;\n  padding: 4px 2px;\n  flex-shrink: 0;\n  width: 16px;\n}\n\n.automation-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.automation-title {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n\n.automation-name {\n  font-weight: 600;\n  font-size: 13.5px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.automation-chip {\n  flex-shrink: 0;\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  color: var(--text-muted);\n  font-size: 10.5px;\n  padding: 1px 6px;\n  line-height: 1.5;\n}\n\n.automation-chip.widget {\n  color: var(--accent);\n  border-color: color-mix(in srgb, var(--accent) 32%, var(--border));\n  background: var(--accent-soft);\n}\n\n.automation-chip.off {\n  color: var(--text-faint);\n}\n\n.automation-meta {\n  font-size: 11.5px;\n  color: var(--text-faint);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.automation-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-shrink: 0;\n}\n\n.side-action.danger {\n  color: var(--error);\n}\n\n.side-action.danger:hover {\n  color: var(--error);\n  background: var(--error-bg);\n}\n\n/* 启停开关（靛蓝 = 唯一强调色） */\n\n.switch {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  background: var(--sidebar-bg);\n  border-radius: 999px;\n  width: 30px;\n  height: 17px;\n  padding: 0;\n  cursor: pointer;\n  position: relative;\n  transition: background 140ms ease-out, border-color 140ms ease-out;\n  flex-shrink: 0;\n}\n\n.switch .knob {\n  position: absolute;\n  top: 1px;\n  left: 1px;\n  width: 13px;\n  height: 13px;\n  border-radius: 50%;\n  background: var(--surface);\n  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);\n  transition: transform 140ms ease-out;\n}\n\n.switch.on {\n  background: var(--accent);\n  border-color: transparent;\n}\n\n.switch.on .knob {\n  transform: translateX(13px);\n}\n\n.switch:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n/* 自动化页右上角「保持系统唤醒」快捷开关（Task 10） */\n\n.keep-awake-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n\n/* 运行历史 */\n\n.automation-runs {\n  list-style: none;\n  margin: 8px 0 0 22px;\n  padding: 8px 0 0;\n  border-top: 1px solid var(--border);\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.automation-runs li {\n  display: flex;\n  align-items: baseline;\n  gap: 10px;\n  min-width: 0;\n}\n\n.automation-runs .run-time {\n  flex-shrink: 0;\n  font-size: 11px;\n  color: var(--text-faint);\n  font-family: var(--font-mono);\n}\n\n.automation-runs .run-status {\n  flex-shrink: 0;\n  font-size: 11.5px;\n  font-weight: 600;\n}\n\n.automation-runs li.ok .run-status {\n  color: var(--success);\n}\n\n.automation-runs li.err .run-status {\n  color: var(--error);\n}\n\n.automation-runs .run-output {\n  flex: 1;\n  min-width: 0;\n  margin: 0;\n  font-family: var(--font-mono);\n  font-size: 11.5px;\n  color: var(--text-muted);\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 96px;\n  overflow: auto;\n  background: var(--sidebar-bg);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  padding: 6px 8px;\n}\n\n.automation-runs-empty {\n  margin: 8px 0 0 22px;\n  padding: 8px 0 0;\n  border-top: 1px solid var(--border);\n  color: var(--text-faint);\n  font-size: 12px;\n}\n\n/* 运行记录 tab：按日分组标题与会话 drill-down 按钮（行头），行内展开历史（任务行）不受其影响 */\n.automation-runs .run-day {\n  display: block;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--text-muted);\n  padding: 10px 0 4px;\n  border-bottom: 1px solid var(--border);\n}\n\n.automation-runs .run-row-btn {\n  flex: 1;\n  display: flex;\n  align-items: baseline;\n  gap: 10px;\n  min-width: 0;\n  padding: 0;\n  border: none;\n  background: none;\n  font: inherit;\n  color: inherit;\n  text-align: left;\n  cursor: pointer;\n  border-radius: var(--radius-sm);\n}\n\n.automation-runs .run-row-btn:hover .run-time,\n.automation-runs .run-row-btn:hover .muted {\n  color: var(--text);\n}\n\n/* 运行记录「删除」：行内不参与换行，垂直居中于输出框 */\n.automation-runs .run-delete {\n  flex-shrink: 0;\n  align-self: center;\n}\n\n/* 任务表单模态（复用 settings-overlay + confirm-modal 容器） */\n\n.automation-form {\n  width: min(520px, 92vw);\n  /* 表单字段多，整模态压到约一半高度（上限 560px / 80vh 取小），标题与底部按钮常驻，中间字段区滚动 */\n  max-height: min(560px, 80vh);\n}\n\n.automation-form-body {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  overflow-y: auto;\n  min-height: 0;\n  padding-right: 4px;\n}\n\n.modal-field {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.modal-input {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--text);\n  padding: 9px 12px;\n  font-size: 14px;\n  font-weight: 400;\n  outline: none;\n}\n\n.modal-input:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.modal-input.slim {\n  width: 140px;\n}\n\n.modal-textarea {\n  appearance: none;\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--text);\n  padding: 9px 12px;\n  font-size: 13px;\n  font-weight: 400;\n  line-height: 1.5;\n  outline: none;\n  resize: vertical;\n  font-family: inherit;\n}\n\n.modal-textarea:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.modal-check {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 13px;\n  cursor: pointer;\n}\n\n.modal-check input {\n  accent-color: var(--accent);\n}\n\n.interval-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n/* ---- 项目看板 ---- */\n\n.board-sub {\n  margin: 0 0 14px;\n  font-size: 12.5px;\n}\n\n.board-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n  gap: 12px;\n}\n\n.board-card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  padding: 14px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  min-width: 0;\n}\n\n.board-card-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 10px;\n}\n\n.board-card-name {\n  font-weight: 700;\n  font-size: 13.5px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.board-card-time {\n  flex-shrink: 0;\n  font-size: 11px;\n  color: var(--text-faint);\n  font-family: var(--font-mono);\n}\n\n.board-card-empty {\n  font-size: 12.5px;\n}\n\n.board-text {\n  margin: 0;\n  font-size: 12.5px;\n  color: var(--text-muted);\n  white-space: pre-wrap;\n  word-break: break-word;\n  max-height: 220px;\n  overflow: auto;\n  background: var(--sidebar-bg);\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  padding: 8px 10px;\n}\n\n.board-table-wrap {\n  overflow: auto;\n  max-height: 240px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n}\n\n.board-table {\n  border-collapse: collapse;\n  width: 100%;\n  font-size: 12px;\n}\n\n.board-table th,\n.board-table td {\n  text-align: left;\n  padding: 5px 10px;\n  border-bottom: 1px solid var(--border);\n  white-space: nowrap;\n  max-width: 220px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.board-table th {\n  position: sticky;\n  top: 0;\n  background: var(--sidebar-bg);\n  color: var(--text-muted);\n  font-weight: 600;\n}\n\n.board-table tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.board-table-more {\n  margin: 6px 0 0;\n  font-size: 11px;\n}\n\n/* 历史会话详情（主区域内嵌，替代原弹窗） */\n\n.history-pane {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 16px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  max-width: 760px;\n  width: 100%;\n  margin: 0 auto;\n}\n\n.history-pane .session-log {\n  flex: 1;\n}\n\n/* 设置「权限」页 */\n\n.perm-pane {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.perm-row {\n  position: relative;\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  padding: 10px 12px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--surface);\n  cursor: pointer;\n}\n\n.perm-row input[type=\"checkbox\"] {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n  appearance: none;\n}\n\n.perm-check {\n  flex-shrink: 0;\n  display: grid;\n  place-items: center;\n  width: 16px;\n  height: 16px;\n  margin-top: 2px;\n  border: 1.5px solid var(--border-strong);\n  border-radius: 4px;\n  background: var(--surface);\n}\n\n.perm-row input[type=\"checkbox\"]:checked + .perm-check {\n  background: var(--accent-soft);\n  border-color: var(--accent);\n}\n\n.perm-row input[type=\"checkbox\"]:checked + .perm-check::after {\n  content: \"\";\n  width: 8px;\n  height: 4px;\n  margin-top: -2px;\n  border-left: 2px solid var(--text);\n  border-bottom: 2px solid var(--text);\n  transform: rotate(-45deg);\n}\n\n.perm-row:focus-within .perm-check {\n  box-shadow: 0 0 0 3px var(--accent-soft);\n}\n\n.perm-text {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.perm-title {\n  font-size: 13.5px;\n  font-weight: 600;\n  color: var(--text);\n}\n\n.perm-desc {\n  font-size: 12px;\n  color: var(--text-muted);\n}\n\n/* composer 局域网指示 chip：可点击跳转设置，覆盖 static 的默认光标 */\n\n.chip-offline {\n  cursor: pointer;\n}\n\n/* ---- 市场页（MarketView，M5 Task 6） ---- */\n\n.market-state-hint {\n  margin-left: auto;\n  font-size: 11px;\n  color: var(--text-muted);\n}\n\n.market-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.market-item {\n  display: flex;\n  align-items: baseline;\n  gap: 10px;\n  flex-wrap: wrap;\n  padding: 10px 14px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--surface);\n}\n\n.market-item .recent-title {\n  font-size: 13.5px;\n  font-weight: 600;\n}\n\n/* P2-2（M26 Task 2，DESIGN.md Typography 硬条款）：版本号等元数据走 JetBrains\n   Mono + tabular-nums——等宽数字列对齐，sha256/体积比对时不跳动。 */\n.market-version {\n  font-style: normal;\n  font-weight: 400;\n  font-size: 12.5px;\n  color: var(--text-muted);\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n}\n\n/* 同 P2-2：承载 sha256/体积的元数据行（安装确认框的校验摘要同口径）。 */\n.market-meta {\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n}\n\n.market-install {\n  margin-left: auto;\n  padding: 5px 14px;\n  font-size: 12.5px;\n}\n\n/* P23（M6 Task 5.1）：此处原用不在 DESIGN.md 调色板的幽灵 token（error 边框的\n   未定义变体，靠 fallback 生效）——改用调色板内真实 token。 */\n.market-error {\n  padding: 18px 20px;\n  border: 1px solid var(--error);\n  border-radius: var(--radius-md);\n  background: var(--error-bg);\n  color: var(--error);\n}\n\n.market-error-title {\n  margin: 0 0 6px;\n  font-size: 14px;\n  font-weight: 600;\n}\n\n.market-sources {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n/* tab 栏（P24）：语义容器包住既有 filter-tab 视觉，间距与 .page-tools 原版面一致。 */\n.market-tabs {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n/* 来源面板（M6 Task 5.1）：provider 开关 + 只读说明，卡片形态承 .market-item。 */\n.market-provider {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 14px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--surface);\n}\n\n.market-provider-options {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.market-provider-option {\n  appearance: none;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  text-align: left;\n  padding: 10px 12px;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-sm);\n  background: var(--bg);\n  color: var(--text);\n  font: inherit;\n  cursor: pointer;\n}\n\n.market-provider-option:hover {\n  border-color: var(--border-strong);\n}\n\n.market-provider-option:focus-visible {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 3px var(--accent-soft);\n  outline: none;\n}\n\n.market-provider-option.on {\n  border-color: var(--accent);\n  background: var(--accent-soft);\n  cursor: default;\n}\n\n.market-provider-option-title {\n  font-size: 13.5px;\n  font-weight: 600;\n}\n\n.market-provider-option-body {\n  font-size: 12.5px;\n  color: var(--text-muted);\n}\n\n.market-provider-option-status {\n  font-size: 11px;\n  color: var(--accent-ink);\n}\n\n/* 本地安装页签（P22）：提示文/输入行/列表的纵向布局，与 sources 页签同观感。 */\n.market-local {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n/* 路径输入（D11）：在 .row 里占据主宽，按钮随内容收缩。 */\n.market-path-input {\n  flex: 1;\n  min-width: 0;\n  width: auto;\n  border-radius: var(--radius-md);\n}\n\n.market-source-disabled {\n  padding: 12px 14px;\n  border: 1px dashed var(--border);\n  border-radius: var(--radius-md);\n  opacity: 0.6;\n}\n\n.market-source-disabled .recent-title {\n  font-size: 13px;\n  font-weight: 600;\n}\n\n/* 待生效变更条（P28，M6 Task 5.3）：取消重启后清单已写入而应用未重启，此条给出\n   显式「立即重启」入口。形态 = info banner（DESIGN.md〈Components〉Banner：\n   info = accent-soft）内嵌一枚动作钮——置主区顶部、不打断布局，也不与\n   warn（琥珀，留给人批准）/ error（红）抢语义。 */\n.banner.market-pending {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  background: var(--accent-soft);\n  color: var(--accent-ink);\n}\n\n.market-pending-text {\n  font-size: 13.5px;\n}\n\n.market-pending .btn {\n  flex: none;\n  margin-left: auto;\n  padding: 5px 14px;\n  font-size: 12.5px;\n}\n\n.market-pending-hint {\n  margin-left: auto;\n  font-size: 12px;\n  color: var(--text-muted);\n}\n\n/* 搜索空态（P1-1/N5，M26 Task 2）：复用 .panel-empty 的观感，只加纵向布局增量\n   （裁定 C2/W3——不造平行类名，market-search-empty 只是同元素上的修饰类）。 */\n.market-search-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n}\n\n/* 空态内的次要动作钮：同 .market-install 的紧凑尺寸口径。 */\n.btn.small {\n  padding: 5px 14px;\n  font-size: 12.5px;\n}\n"
